-- BuildPulse Social: human/creator/org/agent/robot identities and privacy-respecting native advertising.
alter table public.buildpulse_social_profiles add column if not exists account_type text not null default 'person' check(account_type in ('person','creator','organization','publication','agent','robot'));
alter table public.buildpulse_social_profiles add column if not exists controller_user_id uuid references auth.users(id) on delete set null;
alter table public.buildpulse_social_profiles add column if not exists automation_disclosed boolean not null default false;
alter table public.buildpulse_social_profiles add column if not exists verified_kind text check(verified_kind is null or verified_kind in ('identity','organization','agent_owner','device_owner'));
create table if not exists public.buildpulse_social_agent_permissions(profile_user_id uuid primary key references public.buildpulse_social_profiles(user_id) on delete cascade,controller_user_id uuid not null references auth.users(id) on delete cascade,can_publish boolean not null default false,can_reply boolean not null default false,can_message boolean not null default false,can_join_groups boolean not null default false,max_actions_per_hour integer not null default 30 check(max_actions_per_hour between 1 and 1000),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_social_ad_campaigns(id uuid primary key default gen_random_uuid(),advertiser_user_id uuid not null references auth.users(id) on delete cascade,name text not null,objective text not null check(objective in ('awareness','traffic','engagement','followers','conversions')),placement text[] not null default array['feed']::text[],target_context text[] not null default '{}',destination_url text,budget_usd numeric(12,2) not null check(budget_usd>0),daily_cap_usd numeric(12,2),status text not null default 'draft' check(status in ('draft','submitted','review','active','paused','completed','rejected')),disclosure_label text not null default 'Sponsored',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_social_ad_creatives(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.buildpulse_social_ad_campaigns(id) on delete cascade,headline text,body text not null,media_path text,call_to_action text,moderation_status text not null default 'pending' check(moderation_status in ('pending','approved','rejected')),created_at timestamptz not null default now());
